@section('script')
<script>
document.addEventListener('DOMContentLoaded', function () {
    document.querySelectorAll('[data-reconcile]').forEach(button => button.addEventListener('click', function () {
        const form = document.getElementById('reconcile-form');
        form.action = '{{ url('/admin/finance/statement-lines') }}/' + this.dataset.id + '/reconcile';
        document.getElementById('reconcile-label').textContent = this.dataset.label;
        const select = form.elements.financial_entry_id;
        Array.from(select.options).forEach(option => option.hidden = option.value && option.dataset.instrument !== this.dataset.instrument);
        select.value = '';
        bootstrap.Modal.getOrCreateInstance(document.getElementById('reconcile-modal')).show();
    }));
});
</script>
@endsection
